#[test]
public(package) fun debt_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);
    let ctx = scenario_value.ctx();
    let market = object::new(ctx);

    let (mut obligation, cap) = new<MainMarket>(*market.uid_as_inner(), 0, ctx);

    let asset_borrow_index = math::float::from_quotient(15, 10);
    let amount = 1;

    assert!(!obligation.debt_types().contains(&type_name::with_defining_ids<SUI>()));

    // initial borrow
    let borrowed = obligation.try_borrow_asset<MainMarket, SUI>(amount, asset_borrow_index);
    assert!(borrowed == math::float::from(amount));
    let (borrowed, index) = obligation.debt<MainMarket>(type_name::with_defining_ids<SUI>()).snapshot();
    assert!(borrowed == math::float::from(amount));
    assert!(index == asset_borrow_index);
    assert!(obligation.debt_types().contains(&type_name::with_defining_ids<SUI>()));

    // future borrows
    let asset_borrow_index = math::float::from_quotient(21, 10);
    let amount = 1;
    let total_borrowed = obligation.try_borrow_asset<MainMarket, SUI>(amount, asset_borrow_index);
    let (borrowed, index) = obligation.debt<MainMarket>(type_name::with_defining_ids<SUI>()).snapshot();
    assert!(total_borrowed == borrowed);
    assert!(borrowed == math::float::from_quotient(36, 15));
    assert!(index == asset_borrow_index);

    std::unit_test::destroy(market);
    std::unit_test::destroy(scenario_value);
    std::unit_test::destroy(obligation);
    std::unit_test::destroy(cap);
}

#[test]
public(package) fun mint_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);
    let ctx = scenario_value.ctx();
    let market = object::new(ctx);

    let (mut obligation, cap) = new<MainMarket>(*market.uid_as_inner(), 0, ctx);

    let amount = 100;
    let ctoken = sui::coin::mint_for_testing<CToken<MainMarket, SUI>>(amount, ctx).into_balance();

    assert!(!obligation.deposit_types().contains(&type_name::with_defining_ids<SUI>()));

    // initial borrow
    obligation.deposit_ctoken<MainMarket, SUI>(ctoken);
    assert!(obligation.ctoken_amount_by_coin(type_name::with_defining_ids<SUI>()) == amount);

    let withdrawn = obligation.withdraw_ctokens<MainMarket, SUI>(amount / 2);
    assert!(withdrawn.value() == amount / 2);
    assert!(obligation.ctoken_amount_by_coin(type_name::with_defining_ids<SUI>()) == amount / 2);
    std::unit_test::destroy(withdrawn);

    let withdrawn = obligation.withdraw_ctokens<MainMarket, SUI>(amount / 2);
    assert!(withdrawn.value() == amount / 2);
    assert!(obligation.ctoken_amount_by_coin(type_name::with_defining_ids<SUI>()) == 0);
    std::unit_test::destroy(withdrawn);

    std::unit_test::destroy(market);
    std::unit_test::destroy(scenario_value);
    std::unit_test::destroy(obligation);
    std::unit_test::destroy(cap);
}

/// @title Module for hanlding withdraw base asset request from user
/// @notice User use sCoin to redeem the underlying asset
module protocol::withdraw;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::event::emit;
use sui::coin::Coin;

use x_oracle::x_oracle::XOracle;

use protocol::app::ProtocolApp;
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::ctoken::CToken;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_deposit_reward_type;

public struct WithdrawEvent has copy, drop {
    redeemer: address,

    market: TypeName,
    obligation: ID,

    withdraw_asset: TypeName,
    withdraw_amount: u64,
    ctokens_remaining: u64,

    burn_asset: TypeName,
    burn_amount: u64,
    time: u64,
}

public fun withdraw_as_coin<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    ctoken_to_burn: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = sui::clock::timestamp_ms(clock) / 1000;

    let (coin, ctokens_remaining) = market.handle_withdraw<MarketType, CoinType>(
        obligation_owner_cap.id(),
        ctoken_to_burn,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_deposit_reward_type(),
        obligation_owner_cap.id(),
        ctokens_remaining,
        clock
    );

    // emit Redeem Event
    emit(WithdrawEvent {
        redeemer: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        withdraw_asset: type_name::with_defining_ids<CoinType>(),
        withdraw_amount: coin.value(),
        ctokens_remaining,

        burn_asset: type_name::with_defining_ids<CToken<MarketType, CoinType>>(),
        burn_amount: ctoken_to_burn,

        time: now,
    });

    coin
}

#[allow(lint(self_transfer))]
public fun withdraw<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let coin = withdraw_as_coin<MarketType, CoinType>(
        app,
        market,
        obligation_owner_cap,
        coin_decimals_registry, 
        amount, 
        x_oracle, 
        clock, 
        ctx
    );
    transfer::public_transfer(coin, ctx.sender());
}

