// ==================== Constructor =====================
public(package) fun new<MarketType>(
    market_config: MarketConfiguration,
    ctx: &mut TxContext,
): Market<MarketType> {
    let mut market = Market {
        id: object::new(ctx),

        emode_group_registry: emode::new_e_mode_registry(ctx),

        assets: generic_store::new(ctx),
        reserves: generic_store::new(ctx),

        ema_spot_tolerance: generic_store::new(ctx),

        obligations: object_table::new(ctx),
        liquidity_miner: liquidity_miner::new_liquidity_miner(ctx),
    };

    dynamic_field::add(&mut market.id, MarketConfigurationKey {}, market_config);
    dynamic_field::add(&mut market.id, CircuitBreakKey {}, false);
    dynamic_field::add(&mut market.id, ADLRegistryKey {}, new_auto_deleverage_registry(ctx));

    market
}

