   258→   258→public(package) fun handle_mint<MarketType, CoinType>(
   259→   259→    self: &mut Market<MarketType>,
   260→   260→    obligation: ID,
   261→   261→    coin: Coin<CoinType>,
   262→   262→    now: u64,
   263→   263→): (u64, u64) {
   264→   264→    assert!(coin.value() != 0, error::no_zero_amount());
   265→   265→
   266→   266→    let name = type_name::with_defining_ids<CoinType>();
   267→   267→    let deposit_amount = coin.value();
   268→   268→
   269→   269→    let asset = self.assets.load_mut_by_type(name);
   270→   270→    assert!(!asset.deposit_paused(), error::deposit_paused_for_asset());
   271→   271→
   272→   272→    let asset_config = asset.asset_config();
   273→   273→
   274→   274→    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset_config, asset.interest_model(), now);
   275→   275→
   276→   276→    // technically should be in stable coin value, but keep it this way for now
   277→   277→    assert!(
   278→   278→        !reserve.deposit_limit_breached<MarketType>(
   279→   279→            deposit_amount,
   280→   280→            asset_config.max_deposit_amount(),
   281→   281→        ),
   282→   282→        error::market_deposit_limit_exceeded(),
   283→   283→    );
   284→   284→
   285→   285→    let ctoken = reserve.mint_ctokens(coin);
   286→   286→    let ctoken_amount = ctoken.value();
   287→   287→
   288→   288→    // now handle obligation related
   289→   289→    let obligation = self.obligations.borrow_mut(obligation);
   290→   290→    assert!(
   291→   291→        obligation.market_id() == self.id.uid_as_inner(),
   292→   292→        error::obligation_from_different_market(),
   293→   293→    );
   294→   294→    obligation.deposit_ctoken<MarketType, CoinType>(ctoken);
   295→   295→
   296→   296→    // update rate limit deposit 
   297→   297→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
   298→   298→    emode.borrow_mut_deposit_limiter().reduce_outflow(now, deposit_amount);
   299→   299→
   300→   300→    (ctoken_amount, obligation.ctoken_amount_by_coin(name))
   301→   301→}
