   366→   366→public(package) fun handle_borrow<MarketType, CoinType>(
   367→   367→    self: &mut Market<MarketType>,
   368→   368→    obligation_id: ID,
   369→   369→    borrow_amount: u64,
   370→   370→    coin_decimals_registry: &CoinDecimalsRegistry,
   371→   371→    x_oracle: &XOracle,
   372→   372→    clock: &Clock,
   373→   373→    now: u64,
   374→   374→): (Balance<CoinType>, Decimal, Decimal) {
   375→   375→    assert!(borrow_amount != 0, error::no_zero_amount());
   376→   376→
   377→   377→    let name = type_name::with_defining_ids<CoinType>();
   378→   378→
   379→   379→
   380→   380→
   381→   381→    // basic checks
   382→   382→    let asset = self.assets.load_mut_by_type(name);
   383→   383→    assert!(!asset.borrow_paused(), error::borrow_paused_for_asset());
   384→   384→
   385→   385→
   386→   386→
   387→   387→    // load data for later checks
   388→   388→    let asset_config = asset.asset_config();
   389→   389→    let min_borrow_amount = asset_config.min_borrow_amount();
   390→   390→    let asset_max_borrow_amount = asset_config.max_borrow_amount();
   391→   391→
   392→   392→
   393→   393→    let obligation = self
   394→   394→        .obligations
   395→   395→        .borrow_mut(obligation_id);
   396→   396→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   397→   397→    let asset_name = type_name::with_defining_ids<CoinType>();
   398→   398→
   399→   399→    // make sure the outflow is rate limited
   400→   400→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), asset_name);
   401→   401→    let emode_max_borrow_amount = emode.borrow().max_borrow_amount();
   402→   402→    emode.borrow_mut_borrow_limiter().add_outflow(now, borrow_amount);
   403→   403→
   404→   404→    let obligation_old_total_borrow_amount = if (!obligation.has_debt(name)) { float::zero() } else { obligation.debt(name).unsafe_debt_amount() };
   405→   405→
   406→   406→    // refresh only borrow, practically, obligation owner can borrow a bit more due to collateral interest
   407→   407→    refresh_obligation_borrow_interest_with_new_borrow<MarketType>(name, &self.assets, &mut self.reserves, obligation, now);
   408→   408→
   409→   409→    // update obligation
   410→   410→    let borrow_index = self.reserves.load_by_type(name).borrow_index().value();
   411→   411→
   412→   412→    obligation.try_borrow_asset<MarketType, CoinType>(borrow_amount, borrow_index);
   413→   413→    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);
   414→   414→
   415→   415→    // interest updated, should be up to date
   416→   416→    let obligation_new_total_borrow_amount = obligation.debt(name).unsafe_debt_amount();
   417→   417→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   418→   418→
   419→   419→
   420→   420→    // make sure the emode group borrow limit is not breached
   421→   421→    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
   422→   422→    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());
   423→   423→
   424→   424→    let is_obligation_safe = is_obligation_safe(
   425→   425→        emode_group,
   426→   426→        &self.reserves,
   427→   427→        &self.ema_spot_tolerance,
   428→   428→
   429→   429→        self.obligations.borrow(obligation_id),
   430→   430→        coin_decimals_registry,
   431→   431→        x_oracle,
   432→   432→        clock,
   433→   433→    );
   434→   434→    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());
   435→   435→
   436→   436→    // perform borrow
   437→   437→    let reserve = self.reserves.load_mut_by_type(name);
   438→   438→    let balance = reserve.borrow_amount<MarketType, CoinType>(borrow_amount);
   439→   439→
   440→   440→    assert!((*reserve.debt()).ceil() <= asset_max_borrow_amount, error::market_borrow_limit_exceeded());
   441→   441→
   442→   442→    (balance, borrow_index, obligation_new_total_borrow_amount)
   443→   443→}
